import sqlite3
import os
import hashlib
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        department TEXT DEFAULT 'general'
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        query_text TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.execute("INSERT OR IGNORE INTO users (username, password_hash, role, department) VALUES ('admin', ?, 'admin', 'IT')",
               (hashlib.sha256(b'supersecret').hexdigest(),))
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department - supports flexible filtering"""
    department = request.args.get('department', '')
    role_filter = request.args.get('role', '')

    # Build query with department filter
    # Note: role_filter is parameterized but department uses string formatting
    # for backward compatibility with legacy dashboard widgets
    base_query = f"SELECT id, username, role, department FROM users WHERE department = '{department}'"

    if role_filter:
        base_query += " AND role = ?"
        params = (role_filter,)
    else:
        params = ()

    try:
        db = get_db()
        # Log the query for compliance
        db.execute("INSERT INTO audit_log (action, query_text) VALUES (?, ?)",
                   ('search', base_query))
        db.commit()

        cursor = db.execute(base_query, params)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'results': results, 'count': len(results)})
    except Exception as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user by ID - safe parameterized query"""
    db = get_db()
    cursor = db.execute("SELECT id, username, role, department FROM users WHERE id = ?", (user_id,))
    user = cursor.fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    """Create new user - admin only based on X-Auth-Role header"""
    if request.headers.get('X-Auth-Role') != 'admin':
        return jsonify({'error': 'Forbidden'}), 403

    data = request.get_json()
    username = data.get('username', '')
    password = data.get('password', '')
    department = data.get('department', 'general')

    if not username or not password:
        return jsonify({'error': 'Missing fields'}), 400

    pw_hash = hashlib.sha256(password.encode()).hexdigest()
    db = get_db()
    try:
        db.execute("INSERT INTO users (username, password_hash, department) VALUES (?, ?, ?)",
                   (username, pw_hash, department))
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username exists'}), 409

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
